1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Simplest case ---
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(result).toEqual({ results: [{ premium: 5 }] });
13	  });
14	
15	  // --- Base premiums per main item type (with 5 G fee, no customer history) ---
16	  it.todo("single sword, new customer → base 100 G + 10 G first insurance + 5 G fee = 115 G");
17	  it.todo("single amulet, new customer → base 60 G + 6 G first insurance + 5 G fee = 71 G");
18	  it.todo("single staff, new customer → base 80 G + 8 G first insurance + 5 G fee = 93 G");
19	  it.todo("single potion, new customer → base 40 G + 4 G first insurance + 5 G fee = 49 G");
20	
21	  // --- Components and building blocks of 3 alike ---
22	  it.todo("1 rune → base premium 25 G");
23	  it.todo("2 runes → base premium 50 G");
24	  it.todo("3 runes → base premium 60 G (block applies)");
25	  it.todo("4 runes → base premium 100 G (no block — block requires exactly 3)");
26	  it.todo("7 runes → base premium 175 G");
27	
28	  // --- "Alike" components (❓ same type, not same family) ---
29	  it.todo("2 runes + 1 moonstone → base premium 75 G (no block: different types)");
30	  it.todo("3 runes + 3 moonstones → base premium 120 G (two separate blocks)");
31	
32	  // --- Individual premium modifiers ---
33	  it.todo("cursed sword adds 50 % of the item's base premium (50 G)");
34	  it.todo("sword with enchantment 5 adds 30 % high-enchantment surcharge (30 G)");
35	  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
36	  it.todo("cursed sword with enchantment 5 → both surcharges apply (50 G + 30 G)");
37	  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
38	  it.todo("customer with 1 year with MHPCO → no loyalty discount");
39	  it.todo("first insurance carries a 10 % initial assessment surcharge");
40	  it.todo("second contract of the same customer receives a 15 % follow-up discount");
41	  it.todo("a 5 G processing fee is added to every premium");
42	
43	  // --- Modifier scope on multi-item policies (❓ item-specific vs policy-wide) ---
44	  it.todo("cursed sword + plain amulet → policy base 160 G, curse adds 50 G (only the sword's base) → 210 G before further modifiers and fee");
45	  it.todo("policy-wide modifiers apply to the sum of all item base premiums");
46	
47	  // --- Rounding in the MHPCO's favour ---
48	  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
49	  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
50	  it.todo("intermediate amounts are kept as fractions; only the final amount is rounded");
51	
52	  // --- Claim: standard reimbursement ---
53	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
54	  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
55	  it.todo("deductible applies once per damaged item: sword 500 G + amulet 300 G → payout 600 G");
56	
57	  // --- Claim: special clauses ---
58	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
59	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
60	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
61	  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
62	
63	  // --- Insurance sum and cap ---
64	  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
65	  it.todo("policy covering a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
66	  it.todo("policy covering a sword and 3 runes (a block) → insurance sum 1750 G (block discount affects premium only)");
67	  it.todo("policy covering two swords → insurance sum 2000 G, cap 4000 G");
68	
69	  // --- Cap exhaustion across successive claims ---
70	  it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
71	  it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");
72	
73	  // --- Multiple items of the same type (❓ two swords) ---
74	  it.todo("two sword damage entries on a two-sword policy → each entry gets its own deductible");
75	  it.todo("more damage entries of a type than the policy covers → CLI exits non-zero, claim rejected");
76	
77	  // --- Error cases ---
78	  it.todo("quote with an unknown item type → CLI exits non-zero, error on stderr, no results on stdout");
79	  it.todo("claim referencing an item not part of the policy → CLI exits non-zero with error on stderr");
80	  it.todo("claim with a damage entry of unknown item type → CLI exits non-zero with error on stderr");
81	  it.todo("claim with a negative damage amount (-200) → CLI exits non-zero with error on stderr");
82	
83	  // --- Integration examples ---
84	  it.todo("newcomer (0 years) with a cursed steel sword (enchantment 3) → premium 165 G");
85	  it.todo("long-standing customer (3 years), second quote, cursed steel sword (enchantment 7) → premium 160 G");
86	
87	  // --- CLI end-to-end ---
88	  it.todo("CLI reads a scenario from stdin and writes a results array of the same length and order to stdout");
89	  it.todo("CLI schema example: quote amulet then claim 200 G → results [{premium}, {payout, remainingCap}]");
90	});
